var AutoPlayCovenant=class{static ensure(app,options={}){if(!app?.state||!app?.director)return!1;let sequence=app.state.get("activeSequence");if(!sequence||!Array.isArray(sequence.events))return!1;let force=options.force===!0;return app.state.get("userPausedPlayback")&&!force?(app.state.set("isPlaying",!1,!0),!1):(app.director.isPlaying||app.director.play(sequence,0),app.director.isPlaying=!0,app.state.set("isPlaying",!0,!0),!0)}static resume(app){return app?.state?(app.state.set("userPausedPlayback",!1,!0),this.ensure(app,{force:!0})):!1}static pauseByUser(app){!app?.state||!app?.director||(app.director.isPlaying=!1,app.state.set("userPausedPlayback",!0,!0),app.state.set("isPlaying",!1,!0))}static toggle(app){return app?.director?.isPlaying?(this.pauseByUser(app),!1):this.resume(app)}};var FPSCalculator=class{static lastTime=0;static frames=0;static currentFps=60;static currentMs=16.6;static lastUpdate=0;static tick(now){this.lastTime||(this.lastTime=now);let delta=now-this.lastTime;this.currentMs=delta,this.lastTime=now,this.frames++,now-this.lastUpdate>=500?(this.currentFps=Math.round(this.frames*1e3/(now-this.lastUpdate)),this.frames=0,this.lastUpdate=now,this.needsUpdate=!0):this.needsUpdate=!1}static shouldUpdateDOM(){return this.needsUpdate}static getFPS(){return this.currentFps}static getMsPerFrame(){return this.currentMs.toFixed(1)}};var EntityCounter=class{static count(state){if(!state)return 0;let total=0,chars=state.get("characters")||{};total+=Object.keys(chars).length;let scene=state.get("scene")||{};return scene.mountains&&(total+=scene.mountains.length),scene.buildings&&(total+=scene.buildings.length),scene.foliage&&(total+=scene.foliage.length),scene.props&&(total+=scene.props.length),total*125}};var PerfRenderer=class{static render(stats){return`
      <div class="perf-box flex-col gap-1">
        <div class="perf-row flex-space-between">
          <span>FPS:</span> <span class="perf-fps perf-fps-${stats.fps<30?"low":stats.fps<50?"warn":"good"}">${stats.fps}</span>
        </div>
        <div class="perf-row flex-space-between">
          <span>MS:</span> <span>${stats.ms}</span>
        </div>
        <div class="perf-row flex-space-between">
          <span>POLYS:</span> <span>~${stats.entities}</span>
        </div>
      </div>
    `}};var PerformanceMonitor=class{static container=null;static isTracking=!1;static appState=null;static init(state){this.appState=state,this._ensureVessel(),this.isTracking=!1}static toggle(){this.isTracking=!this.isTracking,this.container&&(this.container.style.display=this.isTracking?"block":"none")}static _ensureVessel(){this.container||(this.container=document.createElement("div"),this.container.id="awtsmoos-perf-mount",this.container.className="perf-container hidden",document.body.appendChild(this.container))}static recordFrame(timestamp){if(!(!this.isTracking||!this.container)&&(FPSCalculator.tick(timestamp),FPSCalculator.shouldUpdateDOM())){let stats={fps:FPSCalculator.getFPS(),ms:FPSCalculator.getMsPerFrame(),entities:EntityCounter.count(this.appState)};this.container.innerHTML=PerfRenderer.render(stats)}}};export{AutoPlayCovenant,PerformanceMonitor};
